from collections import deque


def witness_path(revised=False):
    start = ("A", "B")
    queue = deque([start])
    parent = {start: None}

    while queue:
        state = queue.popleft()
        red, blue = state
        if red == "C":
            path = []
            while state is not None:
                path.append(state)
                state = parent[state]
            return path[::-1]

        destinations = {"A": ("B",), "B": ("A",), "C": ()}
        if revised and red == "B":
            next_boxes = ("A", "C")
        else:
            next_boxes = destinations[red]
        for next_red in next_boxes:
            next_state = (next_red, blue)
            if next_state not in parent:
                parent[next_state] = state
                queue.append(next_state)
    return None


def test_original():
    assert witness_path() is None


def test_revised():
    assert witness_path(revised=True) == [
        ("A", "B"), ("B", "B"), ("C", "B")
    ]


if __name__ == "__main__":
    test_original()
    test_revised()
    print("Tests passed")
